<template>
<section class="mt-6 rounded-2xl border border-cyan-200 bg-white p-4 shadow-sm sm:p-5" aria-labelledby="delivery-panel-title">
  <div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-bold uppercase tracking-wide text-cyan-800">Última etapa</p><h3 id="delivery-panel-title" class="text-lg font-bold text-slate-950">Despacho y entrega</h3><p class="text-sm text-slate-600">El inventario ya fue procesado; estas acciones son exclusivamente logísticas.</p></div><span v-if="data?.delivery" class="rounded-full border border-cyan-200 bg-cyan-50 px-3 py-1 text-sm font-semibold text-cyan-900" role="status" aria-live="polite">{{statusLabel(data.delivery.status)}}</span></div>
  <div v-if="loading" class="mt-4 rounded-xl bg-slate-50 p-8 text-center text-slate-700" role="status" aria-live="polite"><i class="pi pi-spin pi-spinner mr-2" aria-hidden="true" />Cargando despacho…</div>
  <div v-else-if="loadError" class="mt-4 flex flex-col gap-3 rounded-xl border border-rose-200 bg-rose-50 p-4 text-rose-900 sm:flex-row sm:items-center sm:justify-between" role="alert"><span>No se pudo consultar el despacho del pedido.</span><button type="button" :disabled="loading || busy" @click="load" class="btn-muted">Reintentar</button></div>
  <div v-else-if="!data?.available" class="mt-4 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 text-center"><p class="text-slate-700">{{data?.message||'El despacho aún no está inicializado.'}}</p><button v-if="data?.can_initialize" type="button" :disabled="busy" @click="act('initialize')" class="btn-primary mt-3">Inicializar despacho</button></div>
  <template v-else>
    <div class="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Info label="Modalidad" :value="methodLabel(data.delivery.method)"/><Info label="Programado" :value="data.delivery.scheduled_at ? formatDateTime(data.delivery.scheduled_at) : 'Sin programación'"/><Info label="Responsable" :value="data.delivery.delivery_user_name||data.delivery.courier_name||data.delivery.pickup_location_name||'Pendiente'"/><Info label="Cobro" :value="paymentText"/></div>
    <div v-if="['contra_entrega','pago_en_sede'].includes(data.order.payment_method)&&!data.payment_transaction" class="mt-3 rounded-xl border border-amber-300 bg-amber-50 p-3 text-sm text-amber-950" role="status">El cobro se registrará únicamente al confirmar una entrega exitosa.</div>
    <div v-if="data.actions.change_method" class="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-3"><button v-for="m in methods" :key="m.value" type="button" :disabled="busy" @click="changeMethod(m.value)" :aria-pressed="data.delivery.method===m.value" :class="data.delivery.method===m.value?'border-blue-600 bg-blue-50 ring-1 ring-blue-600':'border-slate-200 bg-white hover:bg-slate-50'" class="min-h-16 rounded-xl border p-3 text-left focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700 disabled:cursor-not-allowed disabled:opacity-60"><b class="text-slate-900">{{m.label}}</b><div class="text-xs text-slate-600">{{m.help}}</div></button></div>

    <form v-if="data.delivery.method==='store_pickup'&&data.actions.schedule_pickup" @submit.prevent="schedulePickup" class="form-card">
      <h4 class="font-bold">Programar recojo</h4><select v-model="pickup.warehouse_id" required aria-label="Punto de recojo" class="field"><option value="">Punto de recojo</option><option v-for="w in options.warehouses" :key="w.id" :value="w.id">{{w.name}} — {{w.branch?.name}}</option></select><input v-model="pickup.scheduled_at" aria-label="Fecha y hora de recojo" type="datetime-local" class="field"><input v-model="pickup.time_window" aria-label="Horario o franja de recojo" placeholder="Horario o franja" class="field"><input v-model="pickup.authorized_person" aria-label="Persona autorizada para recoger" placeholder="Persona autorizada (opcional)" class="field"><button type="submit" :disabled="busy" class="btn-primary">Guardar y esperar recojo</button>
    </form>
    <form v-if="data.delivery.method==='own_delivery'&&data.actions.assign_driver" @submit.prevent="assignDriver" class="form-card"><h4 class="font-bold">Asignar reparto propio</h4><div v-if="optionsLoading" class="rounded bg-white p-3 text-sm text-gray-600">Cargando repartidores y vehículos…</div><template v-else><div v-if="optionsError" class="rounded border border-red-200 bg-red-50 p-3 text-sm text-red-800">No se pudieron cargar las opciones. <button type="button" class="font-bold underline" @click="loadOptions">Reintentar</button></div><template v-else><div v-if="!options.drivers.length" class="rounded border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">No hay repartidores habilitados. <a class="font-bold underline" href="/admin/delivery-drivers">Registra uno desde Administración → Logística → Repartidores.</a></div><template v-else><select v-model="driver.driver_id" required class="field"><option value="">Repartidor habilitado</option><option v-for="u in options.drivers" :key="u.id" :value="u.id">{{u.code}} — {{u.first_name}} {{u.last_name}} — Disponible</option></select><select v-model="driver.vehicle_id" required class="field"><option value="">Vehículo habilitado</option><option v-for="v in options.vehicles" :key="v.id" :value="v.id">{{v.plate_number||v.code}} — {{v.vehicle_type}} — {{[v.brand,v.model].filter(Boolean).join(' ')||'Sin descripción'}} — Disponible</option></select><div v-if="!options.vehicles.length" class="rounded border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">No hay vehículos habilitados disponibles. <a class="font-bold underline" href="/admin/delivery-vehicles">Registra uno desde Administración → Logística → Vehículos.</a></div><input v-model="driver.scheduled_at" required type="datetime-local" class="field"><textarea v-model="driver.delivery_notes" placeholder="Observaciones" class="field"></textarea><button :disabled="busy||!options.vehicles.length" class="btn-primary">Asignar reparto</button></template></template></template></form>
    <form v-if="data.delivery.method==='external_courier'&&data.actions.assign_courier" @submit.prevent="assignCourier" class="form-card"><h4 class="font-bold">Courier externo manual</h4><input v-model="courier.courier_name" required aria-label="Empresa de courier" placeholder="Empresa de courier" class="field"><input v-model="courier.courier_service" aria-label="Servicio de courier" placeholder="Servicio" class="field"><input v-model="courier.tracking_number" aria-label="Número de guía" placeholder="Número de guía" class="field"><input v-model="courier.tracking_url" aria-label="Dirección de seguimiento del courier" type="url" placeholder="https://seguimiento..." class="field"><input v-model="courier.courier_reference" aria-label="Referencia del courier" placeholder="Referencia" class="field"><button type="submit" :disabled="busy" class="btn-primary">Guardar courier</button></form>

    <div class="mt-4 flex flex-wrap gap-2" role="group" aria-label="Acciones de despacho" :aria-busy="busy"><button v-if="data.actions.dispatch" type="button" :disabled="busy" @click="confirmAct('dispatch','¿Registrar la salida del paquete?')" :class="primaryDeliveryAction === 'dispatch' ? 'btn-primary' : 'btn-muted'">Registrar despacho</button><button v-if="data.actions.start_attempt" type="button" :disabled="busy" @click="act('attempts')" :class="primaryDeliveryAction === 'start_attempt' ? 'btn-primary' : 'btn-muted'">Iniciar intento</button><button v-if="data.actions.out_for_delivery" type="button" :disabled="busy" @click="confirmAct('out-for-delivery','¿Confirmar que el pedido está en camino?')" :class="primaryDeliveryAction === 'out_for_delivery' ? 'btn-primary' : 'btn-muted'">En camino</button><button v-if="data.actions.fail_attempt" type="button" :disabled="busy" @click="failAttempt" class="btn-danger">Intento fallido</button><button v-if="data.actions.reschedule" type="button" :disabled="busy" @click="reschedule" class="btn-muted">Reprogramar</button><button v-if="data.actions.confirm_delivery" type="button" :disabled="busy" @click="confirmOpen=true" :class="primaryDeliveryAction === 'confirm_delivery' ? 'btn-success' : 'btn-muted'">Confirmar entrega</button><button v-if="data.actions.cancel" type="button" :disabled="busy" @click="cancelDelivery" class="btn-danger">Cancelar antes de salida</button></div>

    <div v-if="data.delivery.attempts?.length" class="mt-5"><h4 class="font-bold">Intentos</h4><div v-for="a in data.delivery.attempts" :key="a.id" class="mt-2 rounded border p-3 text-sm"><b>Intento {{a.attempt_number}} · {{statusLabel(a.status)}}</b><div class="text-gray-500">{{formatDateTime(a.started_at||a.scheduled_at)}}</div><p v-if="a.failure_description" class="text-red-700">{{failureLabel(a.failure_reason)}}: {{a.failure_description}}</p></div></div>
    <details class="mt-5 rounded border p-3" @toggle="syncHistory"><summary class="cursor-pointer font-semibold focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700" :aria-expanded="historyExpanded" aria-controls="delivery-history-content">Historial ({{data.delivery.history?.length||0}})</summary><div id="delivery-history-content"><div v-for="h in data.delivery.history" :key="h.id" class="mt-3 border-l-2 border-cyan-300 pl-3 text-sm"><b>{{eventLabel(h.event_type)}}</b><div class="text-xs text-gray-500">{{formatDateTime(h.created_at)}} · {{h.user?.name||'Usuario eliminado'}}</div><p v-if="h.observation">{{h.observation}}</p></div></div></details>
  </template>

  <div v-if="confirmOpen" class="fixed inset-0 z-[70] flex items-center justify-center overflow-y-auto bg-black/50 p-3 sm:p-4" @click.self="!busy && (confirmOpen = false)" @keydown.esc.stop.prevent="!busy && (confirmOpen = false)"><form @submit.prevent="confirmDelivery" class="my-4 max-h-[calc(100dvh-2rem)] w-full max-w-2xl overflow-y-auto rounded-xl bg-white p-5 shadow-xl sm:p-6" role="dialog" aria-modal="true" aria-labelledby="delivery-confirm-title"><div class="flex justify-between gap-3"><h3 id="delivery-confirm-title" class="text-lg font-bold">Confirmar entrega</h3><button type="button" :disabled="busy" aria-label="Cerrar confirmación de entrega" @click="confirmOpen=false" class="min-h-10 min-w-10 rounded text-2xl focus-visible:outline focus-visible:outline-2 focus-visible:outline-blue-700">&times;</button></div><div class="mt-4 grid gap-3 md:grid-cols-2"><input v-model="confirmation.recipient_name" required aria-label="Nombre de quien recibe" placeholder="Nombre de quien recibe" class="field"><select v-model="confirmation.recipient_document_type" required aria-label="Tipo de documento de quien recibe" class="field"><option value="DNI">DNI</option><option value="CE">CE</option><option value="PASSPORT">Pasaporte</option><option value="OTHER">Otro</option></select><input v-model="confirmation.recipient_document_number" required aria-label="Número de documento de quien recibe" placeholder="Número de documento" class="field"><input v-model="confirmation.relationship_to_customer" aria-label="Relación con el cliente" placeholder="Relación con cliente" class="field"><select v-model="confirmation.confirmation_method" required aria-label="Método de confirmación de entrega" class="field"><option value="manual">Manual</option><option value="confirmation_code">Código</option><option value="signature">Firma</option><option value="photo">Foto</option></select><input v-model="confirmation.confirmation_code" aria-label="Código de confirmación opcional" placeholder="Código opcional" class="field"><label class="text-sm">Foto<input ref="photo" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Foto de entrega" class="field"></label><label class="text-sm">Firma<input ref="signature" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Firma de quien recibe" class="field"></label><textarea v-model="confirmation.delivery_notes" aria-label="Observación de entrega" placeholder="Observación" class="field md:col-span-2"></textarea></div><div v-if="['contra_entrega','pago_en_sede'].includes(data?.order.payment_method)" class="mt-4 rounded-xl bg-amber-50 p-3"><label class="flex gap-2 font-semibold"><input v-model="confirmation.money_received" type="checkbox" required> Confirmo que el cobro fue recibido</label><select v-model="confirmation.collection_method" aria-label="Medio de cobro recibido" class="field mt-2"><option value="cash">Efectivo</option><option value="card_terminal">POS</option><option value="bank_transfer">Transferencia</option><option value="other">Otro</option></select><input v-model="confirmation.manual_reference" aria-label="Referencia manual del cobro" placeholder="Referencia opcional" class="field mt-2"></div><div class="mt-5 flex flex-wrap justify-end gap-2"><button type="button" :disabled="busy" @click="confirmOpen=false" class="btn-muted">Volver</button><button :disabled="busy" class="btn-success">{{ busy ? 'Confirmando…' : 'Confirmar cobro y entrega' }}</button></div></form></div>
</section>
</template>
<script setup>
import{computed,defineComponent,h,onMounted,reactive,ref}from'vue';import api from'@/api';import{formatDateTime}from'@/utils/dateTime';import{useToast}from'primevue/usetoast';import{useConfirm}from'primevue/useconfirm';
const props=defineProps({orderId:{type:Number,required:true},initial:{type:Object,default:null}}),emit=defineEmits(['updated']);const toast=useToast(),confirm=useConfirm(),data=ref(props.initial),options=reactive({warehouses:[],drivers:[],vehicles:[]}),loading=ref(!props.initial),loadError=ref(false),busy=ref(false),confirmOpen=ref(false),photo=ref(),signature=ref(),optionsLoading=ref(true),optionsError=ref(false),historyExpanded=ref(false);let optionsRequest=false,deliveryRequest=false;
const methods=[{value:'store_pickup',label:'Recojo en tienda',help:'Cliente recoge en un almacén activo.'},{value:'own_delivery',label:'Reparto propio',help:'Responsable interno habilitado.'},{value:'external_courier',label:'Courier externo',help:'Seguimiento manual por guía.'}],pickup=reactive({warehouse_id:'',scheduled_at:'',time_window:'',authorized_person:''}),driver=reactive({driver_id:'',vehicle_id:'',scheduled_at:'',delivery_notes:''}),courier=reactive({courier_name:'',courier_service:'',tracking_number:'',tracking_url:'',courier_reference:''}),confirmation=reactive({recipient_name:'',recipient_document_type:'DNI',recipient_document_number:'',relationship_to_customer:'',confirmation_method:'manual',confirmation_code:'',delivery_notes:'',money_received:false,collection_method:'cash',manual_reference:''});
const primaryDeliveryAction=computed(()=>{const actions=['dispatch','start_attempt','out_for_delivery','confirm_delivery'].filter(action=>data.value?.actions?.[action]);return actions.length===1?actions[0]:null});
const Info=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('div',{class:'rounded bg-gray-50 p-3'},[h('div',{class:'text-xs uppercase text-gray-500'},p.label),h('b',p.value||'—')])});const paymentText=computed(()=>data.value?.payment_transaction?`${data.value.payment_transaction.status} · ${data.value.payment_transaction.currency} ${data.value.payment_transaction.amount}`:'Pendiente');
const statusLabel=s=>({pending:'Pendiente',scheduled:'Programado',assigned:'Asignado',dispatched:'Despachado',out_for_delivery:'En camino',awaiting_pickup:'Esperando recojo',delivered:'Entregado',failed_attempt:'Intento fallido',rescheduled:'Reprogramado',canceled:'Cancelado',in_progress:'En curso',failed:'Fallido'}[s]||'Estado no disponible');const methodLabel=m=>methods.find(x=>x.value===m)?.label||'Método no disponible';const failureLabel=x=>x?.replaceAll('_',' ')||'';const eventLabel=x=>x?.replaceAll('_',' ')||'';
async function loadOptions(){if(optionsRequest)return;optionsRequest=true;optionsLoading.value=true;optionsError.value=false;try{Object.assign(options,(await api.get('/admin/delivery/options')).data)}catch(e){optionsError.value=true;showError(e)}finally{optionsLoading.value=false;optionsRequest=false}}
async function load(){if(deliveryRequest||busy.value)return;deliveryRequest=true;loading.value=true;loadError.value=false;try{data.value=(await api.get(`/admin/orders/${props.orderId}/delivery`)).data;emit('updated',data.value)}catch(e){loadError.value=true;showError(e)}finally{loading.value=false;deliveryRequest=false}}
async function send(path,payload={},method='post',multipart=false){if(busy.value)return false;busy.value=true;try{const config=multipart?{headers:{'Content-Type':'multipart/form-data'}}:{};data.value=(await api[method](`/admin/orders/${props.orderId}/delivery/${path}`,payload,config)).data;emit('updated',data.value);toast.add({severity:'success',summary:'Despacho actualizado',life:2200});return true}catch(e){showError(e);throw e}finally{busy.value=false}}
const act=path=>send(path);function confirmAct(path,message){if(busy.value)return;confirm.require({message,header:'Confirmación operativa',accept:()=>act(path)})}const changeMethod=m=>send('method',{method:m},'patch');const schedulePickup=()=>send('schedule-pickup',pickup);const assignDriver=()=>send('assign-driver',driver);const assignCourier=()=>send('assign-courier',courier);
function failAttempt(){const reason=window.prompt('Motivo: recipient_absent, incorrect_address, recipient_rejected, unable_to_contact, access_restricted, damaged_package, courier_issue, weather_or_traffic u other');if(!reason)return;const description=window.prompt('Descripción obligatoria del fallo:');if(!description)return;const attempt=[...(data.value.delivery.attempts||[])].reverse().find(a=>a.status==='in_progress');if(attempt)send(`attempts/${attempt.id}/fail`,{failure_reason:reason,failure_description:description},'patch')}
function reschedule(){const scheduled_at=window.prompt('Nueva fecha ISO o local (YYYY-MM-DD HH:mm):');if(scheduled_at)send('reschedule',{scheduled_at})}function cancelDelivery(){const reason=window.prompt('Motivo obligatorio:');if(reason)send('cancel',{reason})}
async function confirmDelivery(){if(busy.value)return;const form=new FormData();Object.entries(confirmation).forEach(([k,v])=>form.append(k,k==='money_received'?(v?'1':'0'):v??''));if(photo.value?.files[0])form.append('delivery_photo',photo.value.files[0]);if(signature.value?.files[0])form.append('recipient_signature',signature.value.files[0]);await send('confirm',form,'post',true);confirmOpen.value=false}
function showError(e){toast.add({severity:'error',summary:'Operación no completada',detail:e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||e.message,life:4500})}
function syncHistory(event){historyExpanded.value=event.currentTarget.open}
onMounted(async()=>{await loadOptions();if(!data.value)await load()});
</script>
<style scoped>.field{@apply w-full rounded border border-gray-300 p-2}.form-card{@apply mt-4 grid gap-3 rounded border bg-gray-50 p-4 md:grid-cols-2}.form-card h4{@apply md:col-span-2}.btn-primary{@apply rounded bg-blue-600 px-3 py-2 text-sm font-semibold text-white disabled:opacity-50}.btn-success{@apply rounded bg-green-600 px-3 py-2 text-sm font-semibold text-white disabled:opacity-50}.btn-danger{@apply rounded bg-red-600 px-3 py-2 text-sm font-semibold text-white disabled:opacity-50}.btn-muted{@apply rounded bg-gray-200 px-3 py-2 text-sm font-semibold}</style>
